def footer():return '''<footer class="footer"><div class="footer-cta"><div class="wrap footer-cta-inner"><div class="footer-cta-copy"><h2>Planning something bigger?</h2><p>Most everyday work can start right here in the Hub. For campaigns, flagship events or new publications, contact the Comms helpdesk early so we can shape it with you.</p></div><div class="footer-cta-actions">'''+a(JIRA,'Contact the Comms helpdesk ↗','button')+'''</div></div></div><div class="footer-base"><div class="wrap footer-base-inner"><a class="footer-brand" href="index.html"><img src="images/skao-logo-white.png" width="64" alt="SKA Observatory"><span>Creative Hub</span></a><nav aria-label="Footer">'''+a('resources.html','Templates and assets')+a('faq.html','Get help')+feedback('Give feedback ↗')+a(CANTO,'Canto Media Library ↗')+'''</nav></div></div></footer><dialog id="searchDialog" aria-labelledby="searchTitle"><div class="dialog-title"><h2 id="searchTitle">Search the Hub</h2><button id="closeSearch" class="close-button" aria-label="Close search">×</button></div><p class="search-scope">Searches Hub pages and guidance. Photos and video are in <a href="'''+CANTO+'''">Canto ↗</a>.</p><form id="searchForm" role="search"><label class="field">What do you need?<input id="searchInput" type="search" maxlength="120" autocomplete="off" placeholder="Ask in your own words, e.g. where is the logo?"></label></form><div id="searchSuggest" class="search-suggest"><div id="recentPages" hidden><h3>Recently viewed</h3><div id="recentList" class="suggest-list"></div></div><div><h3>Quick links</h3><div class="suggest-list"><a href="logos.html">Logo files</a><a href="standard-template.html">Slide template</a><a href="colours-and-type.html">Colours</a><a href="fonts.html">Fonts</a><a href="letterheads.html">Letterheads</a><a href="request.html">Request creative help</a><a href="'''+CANTO+'''">Photos and video in Canto ↗</a></div></div></div><p id="searchStatus" role="status" class="status"></p><div id="searchResults" class="search-results"></div>'''+gethelp.answers_html()+'''<div class="search-fallback"><a href="resources.html">Browse templates and assets →</a><a href="request.html">Ask for help →</a></div></dialog>'''+welcome()+'''<p id="copyAnnounce" class="visually-hidden" role="status"></p>'''+'<script type="application/json" id="hubTitles">'+json.dumps({id:PAGES[f][0] for id,t,f,g in ROUTES if id not in PLANNED}).replace('</','<\\/')+'</script>'+'''<script src="js/theme.js?v='''+ASSET_V+'''" defer></script><script src="js/main.js?v='''+ASSET_V+'''" defer></script>'''
def shell(title,body,current,home=False):
 sidebar=section_sidebar(current,SOURCE_TITLES)
 sec=section_of(current)
 # No breadcrumb: the site is only two levels deep, so the section label above the title links back instead.
 # Section overviews need no label: their title is the section.
 eyebrow='' if current=='resources.html' else ('<a class="eyebrow eyebrow-link" href="'+CHILD_OF[current]+'">'+html.escape(SOURCE_TITLES[CHILD_OF[current]])+'</a>') if current in CHILD_OF else ('<a class="eyebrow eyebrow-link" href="'+sec[2]+'">'+html.escape(sec[1])+'</a>') if sec and sec[2]!=current else '' if sec else '<p class="eyebrow">'+html.escape({'faq.html':'Get help'}.get(current,INTERIOR_META.get(current,{}).get('group','Creative Hub')))+'</p>'
 main=body if home else '<div class="page-band"><div class="page-head">'+eyebrow+'<h1>'+html.escape(title)+'</h1></div></div>'+('<div class="page-grid full-width">' if current in FULL_WIDTH else '<div class="page-grid">'+sidebar)+'<article class="content-body">'+body+'</article>'+('' if current in FULL_WIDTH else TOC_RAIL)+'</div>'
 return arrows(gethelp.rename(gethelp.relink('<!doctype html><html lang="en-GB"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>'+html.escape(title)+' | SKAO Creative Hub</title><link rel="stylesheet" href="css/style.css?v='+ASSET_V+'"><script src="js/boot.js"></script></head><body data-mode="preview">'+header(current)+'<div id="announcement" class="announce" hidden><div class="wrap announce-inner"><span class="announce-tag"><svg width="14" height="14" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M12 2.5c.5 4.6 2.4 6.9 7 7.5-4.6.6-6.5 2.9-7 7.5-.5-4.6-2.4-6.9-7-7.5 4.6-.6 6.5-2.9 7-7.5Z"/><path d="M19 15.5c.2 1.8 1 2.7 2.8 3-1.8.3-2.6 1.2-2.8 3-.2-1.8-1-2.7-2.8-3 1.8-.3 2.6-1.2 2.8-3Z"/></svg>New on the Hub</span><p class="announce-text"><a id="announcementLink" href="updates.html">Hub updates</a></p><button type="button" class="announce-close" aria-label="Dismiss announcement"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><path d="M18 6 6 18M6 6l12 12"/></svg></button></div></div><div class="wrap preview-note">Design preview · Guidance is proposed; library links open the current staff services.</div><main id="main-content" class="wrap" tabindex="-1">'+main+'</main>'+footer()+'</body></html>')))
for name,(title,body) in PAGES.items():
 (D/name).write_text(shell(title,body,name,name=='index.html'))
 (R/'content'/name.replace('.html','.html')).write_text(body)
for folder in ['css','js','images','fonts']:shutil.copytree(R/folder,D/folder,dirs_exist_ok=True)
index=[{'title':t,'href':name,'group':INTERIOR_META.get(name,{}).get('group',''),'excerpt':{'request.html':'Prepare a brief and submit a creative request.','contribute.html':'Share slides, photos, video or corrections for review.'}.get(name) or summary(body),'keywords':text(re.sub(r'<section class="catalogue".*?</section>','',body,flags=re.S))} for name,(t,body) in PAGES.items() if name!='index.html' and name not in gethelp.MOVED]
# Moved pages stay findable by their old names and open the part of Get help that holds them.
index+=[{'title':PAGES[name][0],'href':url,'group':'Get help' if url.startswith(gethelp.HOME) else INTERIOR_META.get(url,{}).get('group',''),'excerpt':('Now part of Common questions: ' if url.startswith(gethelp.HOME) else 'Now part of ')+part+'.','keywords':PAGES[name][0]+' '+part} for name,(url,part) in gethelp.MOVED.items() if url!='index.html' and name not in gethelp.RETIRED and (url.startswith(gethelp.HOME+'#') or not url.startswith(gethelp.HOME))]
# Retired pages people may still look for explain where the work went.
index+=[{'title':PAGES[name][0],'href':name,'group':INTERIOR_META.get(name,{}).get('group',''),'excerpt':eyebrow+'.','keywords':PAGES[name][0]+' '+message} for name,(eyebrow,message,searchable) in gethelp.RETIRED.items() if searchable]
(D/'search-index.json').write_text(json.dumps(index))
# Production uses this same visual shell. Direct task panels are rendered only on home.
prod=shell('$stringEscapeUtils.escapeHtml($page.title)','$page.content','',False)
prod=prod.replace('data-mode="preview"','data-mode="confluence" data-context="$stringEscapeUtils.escapeHtml($contextPath)" data-page-id="$page.id"')
prod=prod.replace('<div class="wrap preview-note">Design preview · Guidance is proposed; library links open the current staff services.</div>','')
# Replace article and homepage based on immutable ID, and use actual page-tree context.
start=prod.index('<main id="main-content"');end=prod.index('</main>',start)+7
main='''<main id="main-content" class="wrap" tabindex="-1">
#if($page.id == $pages.home.id)
'''+home+'''
#else
<div class="page-band">
<div class="page-head">SECTION_EYEBROW<h1>$stringEscapeUtils.escapeHtml($page.title)</h1></div></div>
'''
ROUTE_IDS={filename:id for id,title,filename,group in ROUTES}
# Sidebar per section; section landings and the catalogue are full width.
wide=' || '.join(f'$page.id.toString() == "{ROUTE_IDS[f]}"' for f in sorted(FULL_WIDTH))
chain=f'#if({wide})\n<div class="page-grid full-width">\n'
for sec in SECTIONS:
 key,landing=sec[0],sec[2]
 members=[m for m in members_of(sec) if section_of(m)[0]==key]+[x for x,k in EXTRA.items() if k==key]
 cond=' || '.join(f'$page.id.toString() == "{ROUTE_IDS[m]}"' for m in members)
 chain+=f'#elseif({cond})\n<div class="page-grid">'+section_sidebar(landing,SOURCE_TITLES)+'\n'
main+=chain+'#else\n<div class="page-grid">'+section_sidebar('',SOURCE_TITLES)+'\n#end\n'
main+='''<article class="content-body">
'''
for i,(id,title,filename,group) in enumerate(ROUTES):
 main+=('#if' if i==0 else '#elseif')+f'($page.id.toString() == "{id}")\n'+PAGES[filename][1]+'\n'
main+='''#else
$page.content
#if($page.children.size() > 0)<section class="section" id="library-sections"><h2>Explore this section</h2><ul class="list">#foreach($child in $page.children)<li><a href="$child.absoluteLink">$stringEscapeUtils.escapeHtml($child.title)</a></li>#end</ul></section>#end
#end
</article>'''+TOC_RAIL+'''</div>
#end
</main>'''
prod=prod[:start]+main+prod[end:]
# Route pages carry their Hub section above the title, linking to its overview, matching the sidebar.
crumbs=''
# Pages under another page show that page instead of the section.
for parent in dict.fromkeys(CHILD_OF.values()):
 cond=' || '.join(f'$page.id.toString() == "{ROUTE_IDS[c]}"' for c,p in CHILD_OF.items() if p==parent)
 crumbs+=('#if' if not crumbs else '#elseif')+f'({cond})<a class="eyebrow eyebrow-link" href="{parent}">{SOURCE_TITLES[parent]}</a>\n'
for n,sec in enumerate(SECTIONS):
 key,label,landing=sec[0],sec[1],sec[2]
 members=[m for m in members_of(sec) if section_of(m)[0]==key and m!=landing]+[x for x,k in EXTRA.items() if k==key]
 cond=' || '.join(f'$page.id.toString() == "{ROUTE_IDS[m]}"' for m in members)
 crumbs+=('#if' if not crumbs else '#elseif')+f'({cond})<a class="eyebrow eyebrow-link" href="{landing}">{label}</a>\n'
crumbs+=f'#elseif($page.id.toString() == "{ROUTE_IDS[SECTIONS[0][2]]}"'+''.join(f' || $page.id.toString() == "{ROUTE_IDS[sec[2]]}"' for sec in SECTIONS[1:])+f' || $page.id.toString() == "{ROUTE_IDS["resources.html"]}")\n'
crumbs+=f'#elseif($page.id.toString() == "{ROUTE_IDS["faq.html"]}")<p class="eyebrow">Get help</p>\n'
crumbs+='#else<p class="eyebrow">$displayGroup</p>\n#end\n'
assert 'SECTION_EYEBROW' in prod
prod=prod.replace('SECTION_EYEBROW',crumbs,1)
PAGE_TITLES={'index.html':'SKAO Creative Hub Home','resources.html':'Templates & Assets','presentations.html':'Slide Decks & Presentations','brand.html':'Brand Guidelines','request.html':'Submitting a Request','contribute.html':'How to Submit Your Deck','events.html':'Events Support','help.html':'Tools & Resources'}
PAGE_TITLES.update({filename:title for id,title,filename,group in ROUTES})
for local,title in PAGE_TITLES.items():
 prod=prod.replace('href="'+local+'"', ("href=\"$link.page('CRH', '"+title+"')\"") if "'" not in title else ('href="$link.page(\"CRH\", \"'+title+'\")"'))
 # Links to a part of a page ("working-with-us.html#video") keep their anchor.
 prod=prod.replace('href="'+local+'#', ("href=\"$link.page('CRH', '"+title+"')#") if "'" not in title else ('href="$link.page(\"CRH\", \"'+title+'\")#'))
prod=prod.replace('https://confluence.skatelescope.org/crh/document-templates-381891700.html', "$link.page('CRH', 'Document Templates')")
for slug,title in [('Standard+SKAO+Template','Standard SKAO Template'),('About+SKAO+Master+Deck','About SKAO Master Deck'),('Science+Case+Presentations','Science Case Presentations')]:
 prod=prod.replace('https://confluence.skatelescope.org/display/CRH/'+slug, "$link.page('CRH', '"+title+"')")
for folder in ['css','js','images']:prod=prod.replace('"'+folder+'/','"${theme.baseUrl}/'+folder+'/')
prod=prod.replace('<title>$stringEscapeUtils.escapeHtml($page.title) | SKAO Creative Hub</title>','<title>$stringEscapeUtils.escapeHtml($page.title) | SKAO Creative Hub</title>')
prod=prod.replace('<link rel="stylesheet"', '$webPanels\n$page.resources.meta\n$page.resources.css\n$page.resources.js\n<link rel="stylesheet"',1)
prod=prod.replace('</footer>','<div class="wrap footer-platform">$attributionLine</div></footer>')
